/**
 * Test flow for Updated trigger
 * Tests: Record update trigger with changed fields tracking
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testUpdatedTrigger = Flow(
    {
        $id: Now.ID['test_updated_trigger_flow'],
        name: 'Test Updated Trigger',
        description: 'Tests the Updated trigger with all parameters and changed fields',
    },
    wfa.trigger(
        trigger.record.updated,
        { $id: Now.ID['test_updated_trigger'] },
        {
            table: 'incident',
            condition: 'state!=7',
            run_on_extended: 'false',
            run_when_setting: 'both',
            run_flow_in: 'background',
            run_when_user_setting: 'any',
            trigger_strategy: 'unique_changes',
        }
    ),
    (_params) => {
        // Log all trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_updated_log'] },
            {
                log_level: 'info',
                log_message: `Updated Trigger - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Changed Fields: ${wfa.dataPill(_params.trigger.changed_fields, 'array.object')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)

//Flow 2 with only mandatory inputs and other variations

export const testUpdatedTriggerOnlyMandatory = Flow(
    {
        $id: Now.ID['test_updated_trigger_mandatory_flow'],
        name: 'Test Updated Trigger - Mandatory',
        description: 'Tests the Updated trigger with mandatory inputs and other variations',
    },
    wfa.trigger(
        trigger.record.updated,
        { $id: Now.ID['test_updated_trigger_mandatory'] },
        {
            table: 'incident',
            condition: 'active=true^short_descriptionSTARTSWITHOutage',
            run_on_extended: 'true',
            run_when_setting: 'non_interactive',
            run_flow_in: 'foreground',
            run_when_user_setting: 'one_of',
            trigger_strategy: 'once',
            run_when_user_list: ['62826bf03710200044e0bfc8bcbe5df1'],
        }
    ),
    (_params) => {
        // Log all trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_updated_trigger_mandatory_log'] },
            {
                log_level: 'info',
                log_message: `Updated Trigger - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Changed Fields: ${wfa.dataPill(_params.trigger.changed_fields, 'array.object')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
